import type { CardElement } from "chat";
import { getDb, pgTextArray } from "../db/client";
import { resolveBoundChannelRows } from "../gateway/channels/bound-channels";
import { getChatInstanceManager, isLobuGatewayRunning } from "../lobu/gateway";
import logger from "../utils/logger";
import { resolveSlackUserIdForUser } from "../lobu/stores/chat-identity.js";

interface CreateNotificationParams {
	organizationId: string;
	type:
		| "action_approval_needed"
		| "connection_permission_request"
		| "invitation_received"
		| "browser_auth_expired"
		| "generic"
		| "agent_message";
	title: string;
	body?: string | null;
	resourceType?: string | null;
	resourceId?: string | null;
	resourceUrl?: string | null;
	/** When set, deliver only through this specific bot connection */
	connectionId?: string | null;
	/** When set, deliver only to this Behavior-subscribed channel. */
	channelId?: string | null;
	/** Optional workspace/team guard for channel-scoped delivery. */
	teamId?: string | null;
	/**
	 * Lobu user who owns the change under review (field-change approvals).
	 * When set, bot delivery tries the owner's Slack DM FIRST — resolved via
	 * the owner's workspace-scoped Slack identity — and only falls back
	 * to the configured-target/org-wide channel chain when the owner has no
	 * Slack identity or the DM fails. In-app inbox targeting is unaffected.
	 */
	ownerUserId?: string | null;
	/**
	 * Optional rich card (`chat` `CardElement`) for bot-connection delivery. When
	 * set, the bound channel gets this card instead of the markdown body; the
	 * in-app inbox entry still uses title/body.
	 */
	card?: CardElement | null;
	/**
	 * Optional entity ids to anchor the notification event to (e.g. a watcher's
	 * canvas entity, so the notification threads under the canvas). Stamped onto
	 * the notification event's `entity_ids`.
	 */
	entityIds?: number[];
}

/**
 * Forward a notification to the org's active chat-bot connections so it lands
 * in the bound channel — e.g. a watcher digest posting to #leads.
 *
 * Resolves connections + their Behavior subscriptions straight from Postgres and
 * posts in-process via the chat manager. Every app pod loads every active
 * connection at boot, so the locally-held instance can post regardless of
 * which pod fired the notification — correct under N>1 replicas, no cross-pod
 * routing needed.
 *
 * Best-effort: a connection with no live instance or no binding is skipped
 * without failing the others. A connection bound to several channels posts to
 * each.
 */
interface BotDeliveryTarget {
	connectionId: string;
	platform: string;
	/** Platform-prefixed channel id ready for `chat.channel()`, e.g. "slack:C0123ABCD". */
	channelKey: string;
	/** Workspace/team id from the subscription — keys the owner-DM identity lookup. */
	teamId: string | null;
}

/**
 * Resolve where a notification should be posted.
 *
 * Two branches, UNIONed:
 *
 *   (A) The org's OWN active chat connections JOINed to their subscriptions,
 *       scoped to (org, agent) — the multi-tenant default. A connection with no
 *       subscription has no target; several subscribed channels yield one
 *       target each.
 *
 *   (B) Hosted-preview cross-org delivery. The hosted preview bot is ONE
 *       connection living in its OWN org under a placeholder agent, that fans
 *       out to agents across MANY orgs — a `/lobu link <code>` writes the
 *       subscription under the claim's org, never the connection's. So branch (A)'s
 *       `(org, agent)` JOIN misses it on BOTH columns and proactive
 *       notifications silently drop. This branch resolves the org's bindings
 *       through the shared preview connection, mirroring the inbound
 *       concrete-connection routing. It is gated HARD to previewMode
 *       connections with no `metadata.teamId` (the hosted-bot invariant, same as
 *       `getDefaultConnection`) and is NOT joined on `agent_id`, so a normal
 *       tenant bot can never be used to deliver cross-org.
 *
 * Single-workspace assumption: with exactly one hosted preview connection per
 * platform today, (B) matches on platform alone. When a second hosted workspace
 * appears, persist its Slack team id (e.g. `settings.hostedWorkspaceTeamId`) and
 * add `AND ac.settings->>'hostedWorkspaceTeamId' = b.team_id` so a subscription only
 * resolves the connection actually installed in its workspace (Slack channel ids
 * are workspace-scoped, not global).
 *
 * Exported for testing the delivery path against a real DB.
 */
export async function resolveBotDeliveryTargets(
	organizationId: string,
	opts?:
		| string
		| null
		| {
				connectionId?: string | null;
				channelId?: string | null;
				teamId?: string | null;
		  },
): Promise<BotDeliveryTarget[]> {
	const connectionId =
		typeof opts === "string" || opts === null ? opts : opts?.connectionId;
	const channelId =
		typeof opts === "object" && opts !== null ? opts.channelId : null;
	const teamId = typeof opts === "object" && opts !== null ? opts.teamId : null;
	// Org-wide (no agentId): every channel any of the org's agents is bound to,
	// resolved through the right connection. Shared resolver = one home for the
	// cross-org preview invariant (see bound-channels.ts).
	const rows = await resolveBoundChannelRows(getDb(), {
		organizationId,
		connectionId,
          // A stopped BYO connection must not preempt routing — otherwise it
          // shadows an active OAuth install (an `app_installations` row) for the team
          // (matched first → 503, never falling through to the install).
          connection.status !== "stopped"
      ) || null
    );
  }

  /**
   * Resolve the connection that should handle a webhook we could NOT route by
   * team_id (url_verification challenges, events with no extractable team).
   *
   * Only the hosted shared-app / preview connection is a safe default: it is
   * explicitly marked `settings.previewMode === true` and belongs to no
   * specific tenant. Everything else is tenant-owned — a team-scoped row
   * obviously so, but ALSO a plain org-owned row with empty metadata (a BYO
   * connection created without an OAuth install never gets a `metadata.teamId`,
   * yet still carries that org's bot token). Forwarding an unmatched-team
   * webhook to any tenant-owned row would let one tenant's bot act on (and
   * reply with its own bot token to) another tenant's Slack traffic.
   * `listSlackConnections()` is platform-scoped only (the public `/api/v1/app-webhooks/slack`
   * route carries no org context, so the store's per-tenant predicate doesn't
   * apply) — so we must require the explicit preview marker and otherwise fail
   * closed (return null → handled-by-OAuth-fallback / 503) rather than pick a
   * foreign tenant.
   */
  async getDefaultConnection(): Promise<PlatformConnection | null> {
    const connections = await this.deps.listSlackConnections();
    return (
      connections.find(
        (connection) =>
          connection.settings?.previewMode === true &&
          !connection.metadata?.teamId
      ) || null
    );
  }

  async handleAppWebhook(request: Request): Promise<Response> {
    const body = await request.text();
    const contentType = request.headers.get("content-type") || "";
    const teamJoinEvent = parseSlackTeamJoinEvent(body, contentType);
/**
 * THE single source of truth for "which chat channels can this org / agent reach
 * through which connection" — including the hosted-preview cross-org case.
 *
 * Both the proactive-notification path (`resolveBotDeliveryTargets`) and the
 * native conversation tools (`resolveAddressableTargets`) resolve channels here,
 * so the cross-org preview invariant (the sharpest tenant-safety edge) lives in
 * ONE place and cannot drift between callers.
 *
 * Two branches:
 *   (A) the org's own connections, joined to their bindings on (org, agent,
 *       platform).
 *   (B) hosted-preview cross-org: a binding under THIS org served by the shared
 *       preview connection (which lives in a DIFFERENT org under a placeholder
 *       agent). A `/lobu link <code>` writes the binding under the linking org,
 *       so it never matches branch A's (org, agent) join. Gated HARD to
 *       previewMode connections with no `metadata.teamId` (the hosted-bot
 *       invariant) and NOT joined on agent_id, so a normal tenant bot is never
 *       borrowed cross-org. A NOT EXISTS skips channels the org/agent already
 *       owns via branch A (no double-resolve / double-post).
 *
 * `agentId` (optional) scopes BOTH branches to one agent — set for the
 * conversation tools (an agent may only address ITS OWN bindings), omitted for
 * org-wide notification delivery. `connectionId` (optional) narrows to a single
 * connection (used by targeted notify).
 *
 * Single-workspace assumption: with one hosted preview connection per platform
 * today, (B) matches on platform alone. When a second hosted workspace appears,
 * persist its team id and add `AND pc.settings->>'hostedWorkspaceTeamId' =
 * b.team_id` so a binding only resolves the connection installed in its
 * workspace (channel ids are workspace-scoped, not global).
 */
import type { DbClient } from "../../db/client.js";
import { runtimeConnectionIdToSlug } from "../../lobu/stores/connections-projection.js";

interface BoundChannelRow {
  /** Connection id that owns the post (preview conn for cross-org). */
  id: string;
  platform: string;
  /** As stored on the binding — may be platform-prefixed (`slack:C…`) or bare. */
  channel_id: string;
  team_id: string | null;
  created_at: Date;
}

export async function resolveBoundChannelRows(
  sql: DbClient,
  opts: {
    organizationId: string;
    agentId?: string | null;
    connectionId?: string | null;
  }
): Promise<BoundChannelRow[]> {
  const { organizationId, agentId, connectionId } = opts;
  const slugFilter = connectionId ? runtimeConnectionIdToSlug(connectionId) : null;
  // Agent scope is BINDING ownership (`b.agent_id`), NOT the connection's
  // agent_id — a managed Slack install has agent_id NULL but its bindings still
  // belong to the agent that linked them, so filtering on the connection would
  // hide managed-install channels from agent-scoped list/search/audience paths.
  const agentFilterA = agentId ? sql`AND b.agent_id = ${agentId}` : sql``;
  const agentFilterB = agentId ? sql`AND b.agent_id = ${agentId}` : sql``;
  const ownAgentFilter = agentId ? sql`AND ob.agent_id = ${agentId}` : sql``;
  const connFilterA = slugFilter
    ? sql`AND b.connection_slug = ${slugFilter}`
    : sql``;
  const connFilterB = slugFilter
    ? sql`AND b.connection_slug = ${slugFilter}`
    : sql``;

  // `connections` keys chat rows by `slug` (`agentconn-<id>` for BYO,
  // `slackinst-<id>` verbatim for managed). Callers expect the runtime
  // connection id, so strip the BYO namespace back off in SQL (mirror of
  // `slugToRuntimeConnectionId`). Folded columns: platform → `connector_key`,
  // settings/metadata → `config.{settings,chatMetadata}`, teamId →
  // `external_tenant_id`. Chat rows carry `credential_mode IS NOT NULL`.
  return (await sql`
    SELECT id, platform, channel_id, team_id, created_at FROM (
      SELECT DISTINCT ON (id, platform, channel_id)
        id, platform, channel_id, team_id, created_at
      FROM (
        -- (A) the org's own connections. connection_id is the sole routing key.
        SELECT
          b.runtime_connection_id AS id,
          b.platform, b.channel_id, b.team_id, b.created_at
        FROM behavior_message_subscriptions b
        WHERE b.connection_organization_id = ${organizationId}
          AND b.organization_id = ${organizationId}
          AND b.connection_status = 'active'
          AND b.credential_mode IS NOT NULL
          ${agentFilterA}
          ${connFilterA}

        UNION ALL

        -- (B) hosted-preview cross-org: this org's (agent's) bindings via the
        -- shared preview connection. NO agent_id join on the preview conn; gated
        -- to previewMode + no teamId so a normal bot is never borrowed.
        SELECT
          b.runtime_connection_id AS id,
          b.platform, b.channel_id, b.team_id, b.created_at
        FROM behavior_message_subscriptions b
        WHERE b.organization_id = ${organizationId}
          AND b.connection_status = 'active'
          AND b.credential_mode IS NOT NULL
          AND b.preview_mode
          AND b.connection_team_id IS NULL
          ${agentFilterB}
          ${connFilterB}
          -- Skip channels the org/agent already owns via branch A.
          AND NOT EXISTS (
            SELECT 1
            FROM behavior_message_subscriptions ob
            WHERE ob.connection_organization_id = ${organizationId}
              AND ob.organization_id = ${organizationId}
              AND ob.connection_status = 'active'
              AND ob.credential_mode IS NOT NULL
              ${ownAgentFilter}
              AND ob.platform = b.platform
              AND ob.channel_id = b.channel_id
          )

