/**
 * ClientSDK `behaviors` namespace. Thin, action-complete wrapper over
 * `manageBehaviors` + `getBehavior`.
 *
 * Keep this surface in sync with `ManageBehaviorsSchema`: every
 * `manage_behaviors.action` should either have a named SDK method below or be
 * reachable via `behaviors.manage({ action, ... })`.
 */

import type { Env } from "../../index";
import type {
	BehaviorExecutionConfig,
	BehaviorSource,
	BehaviorTrigger,
	ListBehaviorsArgs,
} from "@lobu/core/contracts/tools/manage-behaviors";
import {
	type ManageBehaviorsArgs,
	manageBehaviors,
} from "../../tools/admin/manage_behaviors";
import { getBehavior } from "../../tools/get_behavior";
import type { ToolContext } from "../../tools/registry";
import { createActionCaller, idArg } from "./action-call";

type BehaviorId = string;
type BehaviorActionInput = Omit<ManageBehaviorsArgs, "action" | "behavior_id"> & {
	behavior_id?: BehaviorId;
};

export type BehaviorListFilter = ListBehaviorsArgs;

export interface BehaviorCreateInput {
	/** Attach the Behavior to an entity. Omit for an org-scoped/global Behavior. */
	entity_id?: number;
	prompt: string;
	sources?: BehaviorSource[];
	triggers?: BehaviorTrigger[];
	slug?: string;
	name?: string;
	description?: string;
	keying_config?: Record<string, unknown>;
	classifiers?: Record<string, unknown>;
	reactions_guidance?: string;
	reaction_script?: string;
	agent_id?: string;
	scheduler_client_id?: string;
	model_config?: Record<string, unknown>;
	execution_config?: BehaviorExecutionConfig;
	tags?: string[];
}

export interface BehaviorUpdateInput {
	behavior_id: BehaviorId;
	triggers?: BehaviorTrigger[];
	agent_id?: string;
	scheduler_client_id?: string;
	model_config?: Record<string, unknown>;
	/** `null` clears a previously-saved config back to NULL/defaults. */
	execution_config?: BehaviorExecutionConfig | null;
}

export interface BehaviorCompleteWindowInput {
	behavior_id: BehaviorId;
	/** JWT obtained from read_knowledge(behavior_id, since, until). */
	window_token?: string;
	/** Multiple page JWTs obtained from read_knowledge for the same Behavior window. */
	window_tokens?: string[];
	extracted_data: Record<string, unknown>;
	replace_existing?: boolean;
	client_id?: string;
	model?: string;
	/** Optional Behavior run id for completion/provenance (from the dispatch prompt). */
	behavior_run_id?: number;
	run_metadata?: Record<string, unknown>;
	template_version_id?: number;
}

export interface BehaviorCreateVersionInput extends BehaviorActionInput {
	behavior_id: BehaviorId;
}

export interface BehaviorVersionDetailsInput {
	behavior_id: BehaviorId;
	version?: number;
}

export interface BehaviorSubmitFeedbackInput {
	behavior_id: BehaviorId;
	window_id: number;
	corrections: Array<{
		field_path: string;
		mutation?: "set" | "remove" | "add";
		value?: unknown;
		note?: string;
	}>;
}

export interface BehaviorGetFeedbackInput {
	behavior_id: BehaviorId;
	window_id?: number;
	limit?: number;
}

export interface BehaviorCreateFromVersionInput {
	version_id: number;
	entity_ids: number[];
	name_pattern?: string;
}

export interface BehaviorsNamespace {
	/** Raw escape hatch for any manage_behaviors action. Prefer named methods. */
	manage(input: ManageBehaviorsArgs): Promise<unknown>;
	list(filter?: BehaviorListFilter): Promise<unknown>;
	get(input: { behavior_id: BehaviorId }): Promise<unknown>;
	create(input: BehaviorCreateInput): Promise<unknown>;
	update(input: BehaviorUpdateInput): Promise<unknown>;
	createVersion(input: BehaviorCreateVersionInput): Promise<unknown>;
	completeWindow(input: BehaviorCompleteWindowInput): Promise<unknown>;
	trigger(input: { behavior_id: BehaviorId }): Promise<unknown>;
	/** Delete one or more Behaviors. */
	delete(input: { behavior_ids: BehaviorId[] }): Promise<unknown>;
	setReactionScript(input: {
		behavior_id: BehaviorId;
		/** TypeScript source. Empty string removes it. */
		reaction_script: string;
	}): Promise<unknown>;
	getVersions(behavior_id: BehaviorId): Promise<unknown>;
	getVersionDetails(
		input: BehaviorId | BehaviorVersionDetailsInput,
	): Promise<unknown>;
	getComponentReference(): Promise<unknown>;
	submitFeedback(input: BehaviorSubmitFeedbackInput): Promise<unknown>;
	getFeedback(input: BehaviorGetFeedbackInput): Promise<unknown>;
	createFromVersion(input: BehaviorCreateFromVersionInput): Promise<unknown>;
}

function normalizeVersionDetailsInput(
	input: BehaviorId | BehaviorVersionDetailsInput,
): { behavior_id: string; version?: number } {
	if (typeof input === "string") {
		return { behavior_id: input };
	}
	return input;
}

export function buildBehaviorsNamespace(
	ctx: ToolContext,
	env: Env,
): BehaviorsNamespace {
	const { manage, action } = createActionCaller(manageBehaviors, env, ctx, "behaviors");

	return {
		manage: (input) => manage(input as Record<string, unknown>),
		list: (filter) => action("list", filter ?? {}),
		get(input) {
			return getBehavior(
				input as never,
				env,
				ctx,
			) as Promise<unknown>;
		},
		create: (input) => action("create", input),
		update: (input) => action("update", input),
		createVersion: (input) => action("create_version", input),
		completeWindow: (input) => action("complete_window", input),
		trigger: (input) => action("trigger", input),
		delete: (input) => action("delete", input),
		setReactionScript: (input) => action("set_reaction_script", input),
		getVersions: (behavior_id) =>
			action("get_versions", {
				behavior_id: idArg(
					"behaviors.getVersions",
					"behavior_id",
					behavior_id,
					"string",
				),
			}),
		getVersionDetails: (input) =>
			action("get_version_details", normalizeVersionDetailsInput(input)),
		getComponentReference: () => action("get_component_reference"),
		submitFeedback: (input) => action("submit_feedback", input),
		getFeedback: (input) => action("get_feedback", input),
		createFromVersion: (input) => action("create_from_version", input),
	};
}
/**
 * ClientSDK `notifications` namespace.
 *
 * `send` wraps the `notify` tool (in-app inbox + bot fan-out). `list` /
 * `markRead` reuse the REST service layer (`listNotifications` / `markAsRead`)
 * so callers can read and ack their own inbox without duplicate SQL. Reading
 * is available through `query_sdk`; acknowledging changes state and requires
 * `run_sdk`.
 */

import type { CardElement } from "chat";
import type { Env } from "../../index";
import { listNotifications, markAsRead } from "../../notifications/service";
import { notify } from "../../tools/admin/notify";
import type { ToolContext } from "../../tools/registry";
import { ToolUserError } from "../../utils/errors";
import { createActionCaller, idArg } from "./action-call";

export interface NotificationsSendInput {
	/** Notification title (≤200 chars). */
	title: string;
	/** Body text (≤1000 chars). */
	body?: string;
	/**
	 * Optional rich card (`chat` `CardElement`) for bot-connection delivery,
	 * rendered to each platform's native format (Block Kit / Adaptive Cards / …).
	 */
	card?: CardElement;
	/**
	 * Who to notify. `"admins"` (default): org admins/owners. `"all"`: every
	 * member. Or an array of specific user IDs.
	 */
	recipients?: "admins" | "all" | string[];
	/** Relative URL the notification links to (e.g. `/acme/entities`). */
	resource_url?: string;
	/** Deliver only through this specific bot connection (its id). */
	connection_id?: string;
	/** Arbitrary JSON payload appended to the body as formatted JSON. */
	data?: Record<string, unknown>;
	/** Attribution when sent from a watcher reaction — both ids are numeric. */
	behavior_source?: { behavior_id: number; window_id: number };
}

export interface NotificationsListInput {
	/** Keyset cursor: return notifications with id strictly less than this. */
	cursor?: number | null;
	/** Page size (service caps at 50; default 20). */
	limit?: number;
	/** When true, only unread notifications. */
	unread_only?: boolean;
}

export interface NotificationsListResult {
	notifications: Record<string, unknown>[];
	nextCursor: number | null;
}

export interface NotificationsNamespace {
	send(input: NotificationsSendInput): Promise<{ notified_count: number }>;
	list(input?: NotificationsListInput): Promise<NotificationsListResult>;
	/**
	 * Mark one of the caller's notifications as read. Accepts a positional id
	 * or `{ notification_id }`.
	 */
	markRead(
		notificationId: number | { notification_id: number },
	): Promise<{ success: true }>;
}

function requireUserId(ctx: ToolContext): string {
	if (!ctx.userId) {
		throw new ToolUserError("Authenticated user required", 401);
	}
	return ctx.userId;
}

export function buildNotificationsNamespace(
	ctx: ToolContext,
	env: Env,
): NotificationsNamespace {
	const { action } = createActionCaller(notify, env, ctx, "notifications");

	return {
		send: (input) => action("send", input),
		async list(input) {
			const userId = requireUserId(ctx);
			return listNotifications({
				organizationId: ctx.organizationId,
				userId,
				cursor: input?.cursor ?? null,
				limit: input?.limit,
				unreadOnly: input?.unread_only ?? false,
			});
		},
		async markRead(notificationId) {
			const userId = requireUserId(ctx);
			const id = idArg(
				"notifications.markRead",
				"notification_id",
				notificationId,
				"number",
			) as number;
			const updated = await markAsRead(ctx.organizationId, userId, id);
			if (!updated) {
				throw new ToolUserError("Not found or already read", 404);
			}
			return { success: true as const };
		},
	};
}

/**
 * ClientSDK `conversations` namespace. Thin wrapper over `manageConversations`.
 *
 * A conversation is the durable unit an agent talks over — history + its frozen
 * sandbox realm both live here (see the `conversations` entity). `send` drives a
 * turn against one; the reply reads back on the same conversation id.
 */

import type { Env } from "../../index";
import { manageConversations } from "../../tools/admin/manage_conversations";
import type { ToolContext } from "../../tools/registry";
import { createActionCaller } from "./action-call";

export interface ConversationsListInput {
  agent_id: string;
}

export interface ConversationsGetInput {
  agent_id: string;
  /** Defaults to "web" (the app-owned realm). */
  platform?: string;
  conversation_id: string;
}

export interface ConversationsSendInput {
  agent_id: string;
  /** Resume an exact conversation; wins over `thread`. */
  conversation_id?: string;
  /** Open/resume a named web thread (own history + own pinned sandbox). */
  thread?: string;
  text: string;
  /** Per-message `provider/model` override. */
  model?: string;
  /** Await the reply (default true); false returns immediately with the id. */
  wait?: boolean;
  /** [wait=true] Max wait (ms). Default 45000, capped at 170000. */
  timeout_ms?: number;
}

export interface ConversationsNamespace {
  manage(input: Record<string, unknown>): Promise<unknown>;
  list(input: ConversationsListInput): Promise<unknown>;
  get(input: ConversationsGetInput): Promise<unknown>;
  send(input: ConversationsSendInput): Promise<unknown>;
}

export function buildConversationsNamespace(
  ctx: ToolContext,
  env: Env,
): ConversationsNamespace {
  const { manage, action } = createActionCaller(
    manageConversations,
    env,
    ctx,
    "conversations",
  );

  return {
    manage,
    list: (input) => action("list", input),
    get: (input) => action("get", input),
    // `send` returns a discriminated result whose `status` is part of the
    // contract — "error" and "timeout" are NON-throwing outcomes the caller
    // must branch on. Route it through `manage` (the raw handler) rather than
    // `action`, whose failureMessage() turns status:"error"/"timeout" into a
    // thrown ClientSdkActionError. A genuine fault (bad input, agent-not-found)
    // still throws — the handler raises ToolUserError for those.
    send: (input) => manage({ ...input, action: "send" }),
  };
}
